package org.apache.commons.io.input;

import static org.junit.jupiter.api.Assertions.assertEquals;

import java.io.InputStream;

import org.junit.jupiter.api.Test;

/**
 * Tests {@link NullInputStream#skip(long)}, verifying how many bytes are skipped
 * as the stream position advances and what happens once the end of file is reached.
 */
public class NullInputStreamTest_testSkip {

    /**
     * A concrete {@link NullInputStream} whose generated byte values encode the
     * stream position, so reads can be asserted against the expected position.
     */
    private static final class TestNullInputStream extends NullInputStream {

        TestNullInputStream(final int size) {
            super(size);
        }

        TestNullInputStream(final int size, final boolean markSupported, final boolean throwEofException) {
            super(size, markSupported, throwEofException);
        }

        @Override
        protected int processByte() {
            return (int) getPosition() - 1;
        }

        @Override
        protected void processBytes(final byte[] bytes, final int offset, final int length) {
            final int startPos = (int) getPosition() - length;
            for (int i = offset; i < length; i++) {
                bytes[i] = (byte) (startPos + i);
            }
        }
    }

    /** End-of-file marker returned by {@code skip} when {@code throwEofException} is disabled. */
    private static final int EOF = -1;

    @Test
    void testSkip() throws Exception {
        // Stream of 10 bytes, mark supported, returns -1 (instead of throwing) at EOF.
        try (InputStream input = new TestNullInputStream(10, true, false)) {
            // Read the first two bytes; position advances to 2.
            assertEquals(0, input.read(), "Read 1");
            assertEquals(1, input.read(), "Read 2");

            // Skip 5 bytes; position advances from 2 to 7.
            assertEquals(5, input.skip(5), "Skip 1");

            // Read the byte at position 7; position advances to 8.
            assertEquals(7, input.read(), "Read 3");

            // Only 2 bytes remain (positions 8 and 9), so skip(5) skips just 2.
            assertEquals(2, input.skip(5), "Skip 2");

            // Already at EOF: every further skip returns -1.
            assertEquals(EOF, input.skip(5), "Skip 4 (EOF)");
            assertEquals(EOF, input.skip(5), "Skip 5 (EOF)");
        }
    }
}
